insert into public.course_chapters(id,position,title,summary,icon,status) values ('464f9258-e342-55dd-aad5-3c85a17fcc9d',0,'Avant de commencer','Obtenir son permis au Sénégal, définitions et notions de base.','🎓','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('4aa937bf-83c3-506f-b83b-a6902a9e14bc','464f9258-e342-55dd-aad5-3c85a17fcc9d',0,'Comment obtenir son permis au Sénégal',4,'[{"t": "p", "x": "Le permis de conduire est obligatoire pour tout conducteur de véhicule motorisé de plus de 125 cm³. Il existe plusieurs catégories, définies selon le poids du véhicule et le nombre de passagers. Pour l''obtenir, il faut réussir l''examen du Code de la route, puis celui de la conduite."}, {"t": "h", "x": "1. S''inscrire dans une auto-école"}, {"t": "p", "x": "L''auto-école s''occupe de tout : elle assure votre formation théorique et pratique. Conditions à remplir :"}, {"t": "ul", "x": ["Avoir 18 ans pour le permis de catégorie B (léger)", "Avoir 25 ans pour les permis de type C (lourd) et D (transport)"]}, {"t": "h", "x": "Documents à fournir"}, {"t": "ul", "x": ["4 photos d''identité", "Un certificat médical (pour la vision)", "Un certificat de résidence datant d''au moins 3 mois (fait à Dakar)", "Une photocopie légalisée du passeport ou de la carte d''identité nationale"]}, {"t": "h", "x": "Les tarifs"}, {"t": "p", "x": "Ils dépendent de l''auto-école : en général entre 100 000 et 250 000 FCFA, payables en plusieurs fois. Pour les étudiants, des tarifs privilégiés existent, autour de 90 000 FCFA."}, {"t": "h", "x": "2. L''apprentissage"}, {"t": "p", "x": "Les cours théoriques durent généralement 21 jours, à raison de 2 h ou 3 h par semaine. Le moniteur prend ensuite rendez-vous auprès de l''organisme chargé de l''examen. L''examen dure environ 15 minutes, à l''écrit ou à l''oral, avec autour de 25 questions. Les candidats retenus passent ensuite l''examen de conduite."}, {"t": "p", "x": "Pour la conduite, le candidat est encadré par un moniteur pendant 15 à 20 jours. L''examen porte généralement sur la maîtrise de la conduite et le créneau."}, {"t": "h", "x": "3. Où passer l''examen ?"}, {"t": "p", "x": "Les examens sont organisés par un département du ministère des Transports. À Dakar, la théorie se passe au Front de terre, près de la gendarmerie, et la pratique au stade Léopold Sédar Senghor. Le permis est remis dans un délai de 21 jours après validation."}, {"t": "key", "x": "À retenir : 18 ans pour la catégorie B, 25 ans pour C et D. Examen du code : environ 15 minutes et environ 25 questions."}, {"t": "quiz", "q": "À partir de quel âge peut-on passer le permis de catégorie B ?", "o": ["16 ans", "18 ans", "21 ans", "25 ans"], "a": 1, "e": "La catégorie B (léger) s''obtient à 18 ans ; 25 ans pour les catégories C et D."}, {"t": "quiz", "q": "Environ combien de questions comporte l''examen du code ?", "o": ["10", "25", "50", "100"], "a": 1, "e": "Le candidat répond à environ 25 questions en 15 minutes environ."}]'::jsonb,'Informations pratiques (tarifs, lieux, délais) reprises telles quelles du cours : à vérifier et à mettre à jour par l''auto-école.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('94cd01d1-1fb2-5116-8214-7de0fbf76eac','464f9258-e342-55dd-aad5-3c85a17fcc9d',1,'Définition et notions de base',3,'[{"t": "def", "x": [["Le code de la route", "Ensemble des lois et règlements relatifs à l''utilisation des voies publiques (trottoirs, chaussées, autoroutes…) par les piétons, cyclistes, utilisateurs de deux-roues à moteur, automobilistes, routiers, etc."], ["Pourquoi le respecter ?", "Le non-respect expose à des sanctions de divers niveaux selon la gravité de l''infraction : rappel à l''ordre, amende, voire peine de prison."], ["À quoi sert-il ?", "Il régit la manière dont un usager doit se comporter sur la voie publique, définit les droits et les devoirs des usagers et détermine comment assurer une circulation sûre et fluide."], ["Usager de la route", "Toute personne qui utilise la voie publique."], ["Piéton", "Quiconque se déplace à pied. Sont assimilés aux piétons : celui qui conduit à la main une brouette, une voiture d''enfant, un caddie ou un autre véhicule sans moteur ; celui qui conduit à la main une bicyclette ou un cyclomoteur à deux roues ; les utilisateurs d''engins de déplacement qui roulent à l''allure du pas."], ["Conducteur", "Toute personne qui assure la direction d''un véhicule, ou qui guide ou garde des animaux de trait, de charge, de monture ou des bestiaux."]]}, {"t": "quiz", "q": "Qui est assimilé à un piéton ?", "o": ["Celui qui roule à vélo", "Celui qui conduit à la main une bicyclette", "Un automobiliste arrêté", "Un motard"], "a": 1, "e": "Celui qui conduit à la main une bicyclette ou un cyclomoteur à deux roues est assimilé à un piéton."}, {"t": "quiz", "q": "Que risque celui qui ne respecte pas le code de la route ?", "o": ["Rien", "Uniquement une amende", "Des sanctions selon la gravité : rappel à l''ordre, amende, prison", "Uniquement un retrait de permis"], "a": 2, "e": "Les sanctions vont du rappel à l''ordre à l''amende, voire à la peine de prison."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('1dd07557-a8de-5cfc-a6c2-81e7e105b1d4','464f9258-e342-55dd-aad5-3c85a17fcc9d',2,'La voie publique et ses parties',6,'[{"t": "img", "src": "/cours/p4_1.jpg", "cap": "Les parties de la voie publique"}, {"t": "def", "x": [["Voie publique", "Partie située entre deux rangées de maisons (jardins privés non compris) ou entre deux limites de propriétés, habituellement les bords des fossés."], ["Rue", "Voie publique en agglomération ou bordée en tout ou en partie d''immeubles, avec partage de l''espace entre les usagers. Les voiries en zone 30 ou en zone résidentielle sont des rues."], ["Chaussée", "Partie revêtue de matériaux en dur, aménagée pour la circulation des véhicules. Toute voie revêtue en dur est une chaussée, même si le matériau est du gravier ou de la cendrée."], ["Bande de circulation", "Partie d''une chaussée divisée, dans le sens longitudinal, par une ou plusieurs lignes blanches continues ou discontinues."], ["Piste cyclable", "Partie de la voie publique réservée aux bicyclettes et cyclomoteurs à deux roues de classe A. Elle ne fait pas partie de la chaussée. Elle est indiquée par les signaux D7, D9 ou des marques routières."], ["Trottoir", "Partie de la voie publique, en saillie ou non, aménagée pour la circulation des piétons, revêtue en dur et clairement séparée des autres parties."], ["Accotement de plain-pied", "Espace entre la chaussée et un fossé, un talus ou des limites de propriétés, au même niveau que la chaussée, généralement en matériau meuble et peu praticable pour les piétons."], ["Accotement en saillie", "Même espace, mais surélevé par rapport à la chaussée."], ["Terre-plein", "Aménagement longitudinal qui sépare les chaussées (hors marquages routiers)."], ["Îlot directionnel", "Aménagement sur la chaussée destiné à canaliser la circulation, par marquage, surélévation ou les deux."], ["Carrefour", "Lieu de rencontre de deux ou plusieurs voies publiques. Il peut avoir la forme d''un +, d''un T, d''un Y, d''un K."], ["Place", "Espace ouvert où aboutissent une ou plusieurs voies publiques, où la circulation et d''autres activités sont organisées ensemble."], ["Rond-point", "Voirie où la circulation se fait dans un seul sens autour d''un dispositif central, signalée par les signaux D5, avec des accès pourvus des signaux B1 ou B5."], ["Sentier", "Voie publique étroite réservée aux piétons et aux véhicules n''exigeant pas plus d''espace (vélos, cyclomoteurs, motos à deux roues)."], ["Chemin de terre", "Voie publique plus large qu''un sentier mais non revêtue en dur, donc non aménagée pour la circulation des véhicules en général."], ["Passage à niveau", "Croisement total ou partiel d''une voie publique par une ou plusieurs voies ferrées établies hors de la chaussée."], ["Site spécial franchissable", "Partie de la voie publique réservée aux transports en commun (signal F18, marquage « Bus ou Tram », lignes continues de part et d''autre). Il ne fait pas partie de la chaussée."]]}, {"t": "quiz", "q": "La piste cyclable fait-elle partie de la chaussée ?", "o": ["Oui", "Non"], "a": 1, "e": "La piste cyclable ne fait pas partie de la chaussée."}, {"t": "quiz", "q": "Un carrefour peut avoir la forme…", "o": ["d''un +, T, Y ou K", "uniquement d''un +", "d''un cercle uniquement", "d''un triangle"], "a": 0, "e": "Un carrefour peut prendre toutes sortes de formes : +, T, Y, K."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('ef7f07e9-1e0a-5a94-a71e-458b861d3566','464f9258-e342-55dd-aad5-3c85a17fcc9d',3,'Zones et lieux particuliers',6,'[{"t": "def", "x": [["Zone résidentielle ou zone de rencontre", "Voies publiques aménagées dont les accès sont indiqués par les signaux F12a et les sorties par F12b. Dans la zone résidentielle, l''habitat est prépondérant ; la zone de rencontre est similaire mais ouverte à l''artisanat, au commerce, au tourisme, à l''enseignement et aux activités récréatives."], ["Zone 30", "Voie publique dont le début et la fin sont délimités par les signaux F4a et F4b."], ["Agglomération", "Espace comprenant des immeubles bâtis, dont les accès et les sorties sont indiqués par les signaux F1 et F3."], ["Autoroute", "Voie publique dont le commencement ou l''accès est indiqué par le signal F5 et dont la fin est indiquée par le signal F7."], ["Route pour automobiles", "Voie publique dont le commencement est indiqué par le signal F9 et la fin par le signal F11."], ["Chemin réservé aux piétons, cyclistes et cavaliers", "Commencement indiqué par F99a ou F99b, fin indiquée par F101a ou F101b."], ["Zone piétonne", "Voies publiques dont l''accès est indiqué par le signal F103 et la sortie par F105."], ["Rue réservée au jeu", "Voie publique temporairement, à certaines heures, pourvue de barrières à ses accès, avec le signal C3 complété par un panneau « rue réservée au jeu »."], ["Abords d''école", "Zone d''une ou plusieurs voies publiques incluant un accès à une école, délimitée par les signaux F4a et F4b. Le signal A23 est associé au signal F4a."], ["Circulation locale", "Voie accessible uniquement aux riverains et visiteurs, aux véhicules de livraison et d''entretien, aux véhicules prioritaires, aux cyclistes et aux cavaliers."]]}, {"t": "img", "src": "/cours/p7_1.jpg", "cap": "Fin d''autoroute"}, {"t": "img", "src": "/cours/p8_1.jpg", "cap": "Chemin réservé aux piétons, cyclistes et cavaliers"}, {"t": "img", "src": "/cours/p8_2.jpg", "cap": "Rue scolaire"}, {"t": "img", "src": "/cours/p9_1.jpg", "cap": "Abords d''école et zone 30"}, {"t": "h", "x": "Voie publique, terrain public, terrain non public"}, {"t": "ul", "x": ["Voie publique : toutes les voies mises à la disposition des usagers, y compris les voies privées qui ont l''aspect d''une voie publique.", "Terrain public : terrain librement accessible au public (parking de grande surface).", "Terrain non public : accessible à un nombre déterminé de personnes (parking privé payant, terrain de football clôturé)."]}, {"t": "key", "x": "En principe, le code de la route s''applique uniquement à la voie publique. Sur les lieux publics, il n''y a pas de poursuites pénales pour les infractions de circulation, mais bien pour la conduite sous influence, le délit de fuite et l''assurance. Toute voie publique est un lieu public."}, {"t": "quiz", "q": "Où le code de la route s''applique-t-il en principe ?", "o": ["Partout", "Uniquement sur la voie publique", "Uniquement sur autoroute", "Uniquement en ville"], "a": 1, "e": "En principe, le code s''applique uniquement à la voie publique."}, {"t": "quiz", "q": "Un parking privé payant est…", "o": ["une voie publique", "un terrain public", "un terrain non public"], "a": 2, "e": "Il est accessible à un nombre déterminé de personnes : c''est un terrain non public."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('58f24442-ddd4-543d-8cd0-c709f95375c1',1,'Signalisation verticale','Les panneaux de danger, d''obligation, d''interdiction, d''indication et les balises.','🚸','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('43681d25-ad7f-5a16-bfcc-4f2da8183966','58f24442-ddd4-543d-8cd0-c709f95375c1',0,'Les 4 familles de panneaux',4,'[{"t": "p", "x": "La signalisation verticale comprend deux types : les panneaux et les balises. Le mot « panneau » désigne à la fois le dispositif (un poteau) et le signal proprement dit. Les panneaux sont placés à côté des routes, sur les trottoirs ou accotements."}, {"t": "flip", "x": [["Triangle, bordure rouge", "DANGER : annoncé à 50 m en agglomération, 150 m en dehors"], ["Rond, fond blanc, bordure rouge", "INTERDICTION, ordre ou prescription : à l''endroit même"], ["Rond, fond bleu, bordure blanche", "OBLIGATION : à l''endroit même"], ["Carré ou rectangle, fond bleu ou blanc", "INDICATION : à l''endroit ou avant, selon les besoins"]]}, {"t": "img", "src": "/cours/p11_1.jpg", "cap": "Forme, couleur, annonce et signification"}, {"t": "tbl", "h": ["Forme", "Couleur", "Annoncé à", "Signifie"], "r": [["Triangle", "Rouge et blanc", "50 m en agglomération, 150 m en dehors", "Danger"], ["Rond", "Rouge et blanc", "À l''endroit", "Ordre, interdiction ou prescription"], ["Rond", "Bleu foncé et blanc", "À l''endroit", "Obligation"], ["Carré", "Bleu foncé et blanc", "À l''endroit ou avant, selon les besoins", "Indication"]]}, {"t": "key", "x": "Le triangle = un danger, le rond = un ordre, le carré = une indication."}, {"t": "quiz", "q": "Quelle forme ont les panneaux de danger ?", "o": ["Ronde", "Triangulaire", "Carrée", "Octogonale"], "a": 1, "e": "Les panneaux de danger sont triangulaires, à fond blanc et bordure rouge."}, {"t": "quiz", "q": "Un panneau rond à fond bleu indique…", "o": ["un danger", "une interdiction", "une obligation", "une indication"], "a": 2, "e": "Rond, fond bleu, bordure blanche : obligation."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('99f7eb26-493c-5c3b-a212-9892d962a8bf','58f24442-ddd4-543d-8cd0-c709f95375c1',1,'Les panneaux de danger',8,'[{"t": "p", "x": "Les panneaux de danger sont triangulaires, à fond blanc et bordure rouge. Chaque panneau annonce un danger précis à l''aide d''un symbole noir. Ils permettent d''anticiper le danger : le conducteur doit ralentir et maintenir sa vigilance."}, {"t": "key", "x": "Ils sont implantés avant la zone dangereuse : 50 mètres en agglomération (en ville), 150 mètres hors agglomération. Exception : les panneaux « double sens de circulation »."}, {"t": "p", "x": "On les appelle aussi panneaux d''annonce : ils annoncent un danger, de 0 à 50 m en agglomération et 150 m hors agglomération."}, {"t": "img", "src": "/cours/p12_1.jpg", "cap": "Type A – Signalisation de danger"}, {"t": "img", "src": "/cours/p13_1.jpg", "cap": "Panneaux 1 à 8"}, {"t": "ol", "x": ["Virage à droite", "Virage à gauche", "Succession de virages, le 1er à droite (le second peut être à gauche mais aussi à droite)", "Succession de virages, le 1er à gauche (le second peut être à droite mais aussi à gauche)", "Cassis ou dos d''âne", "Ralentisseur", "Chaussée rétrécie", "Chaussée rétrécie par la droite"]}, {"t": "img", "src": "/cours/p14_1.jpg", "cap": "Panneaux 9 à 16"}, {"t": "ul", "x": ["9. Chaussée rétrécie par la gauche", "10. Chaussée particulièrement glissante", "11. Pont mobile", "12. Passage à niveau avec barrières à fonctionnement manuel", "13. Passage à niveau sans barrière ni demi-barrière", "14. Traversée de voies de tramways", "15. Endroit fréquenté par les enfants", "16. Passage pour piétons (signal d''annonce)"]}, {"t": "img", "src": "/cours/p14_2.jpg", "cap": "Panneaux 17 à 24"}, {"t": "ul", "x": ["17. Danger pour lequel il n''existe pas de symbole correspondant", "18 et 19. Passage d''animaux domestiques", "20. Passage d''animaux sauvages (cerfs, sangliers, renards…)", "21. Passage de cavaliers", "22. Descente dangereuse (10 % = descendre de 10 m tous les 100 m parcourus)", "23. Annonce de feux tricolores", "24. Circulation dans les 2 sens à partir du panneau"]}, {"t": "img", "src": "/cours/p15_1.jpg", "cap": "Panneaux 25 à 33"}, {"t": "ul", "x": ["25. Risque de chute de pierres ou présence de pierres tombées sur la route", "26. Débouché sur un quai ou une berge", "27. Débouché de cyclistes venant de droite ou de gauche", "28. Traversée d''une aire de danger aérien", "29. Risque de fort vent latéral", "30. Carrefour à sens giratoire avec priorité aux usagers circulant sur l''anneau", "31. « Cédez le passage » aux véhicules débouchant de la ou des routes situées à sa droite", "32. Intersection avec une route dont les usagers doivent céder le passage (priorité temporaire pour ceux qui circulent tout droit)", "33. Annonce de nappes de brouillard ou de fumée épaisse"]}, {"t": "quiz", "q": "À quelle distance un panneau de danger est-il implanté hors agglomération ?", "o": ["50 m", "100 m", "150 m", "300 m"], "a": 2, "e": "150 m hors agglomération, 50 m en agglomération."}, {"t": "quiz", "q": "Que doit faire le conducteur devant un panneau de danger ?", "o": ["Accélérer", "Ralentir et rester vigilant", "S''arrêter", "Klaxonner"], "a": 1, "e": "Il doit anticiper le danger : ralentir et maintenir sa vigilance."}, {"t": "quiz", "q": "Que signifie « 10 % » sur un panneau de descente dangereuse ?", "o": ["10 m de descente tous les 100 m parcourus", "10 km/h maximum", "10 m de visibilité", "Une descente de 10 km"], "a": 0, "e": "10 % : on descend de 10 m tous les 100 m parcourus."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('804ca8db-ebe9-55d2-bd20-3ba05ba36124','58f24442-ddd4-543d-8cd0-c709f95375c1',2,'Les panneaux d''obligation',5,'[{"t": "p", "x": "Les panneaux d''obligation font partie de la signalisation verticale. Ils obligent les usagers à respecter certaines prescriptions et règles à partir du panneau ou devant celui-ci."}, {"t": "p", "x": "Ils peuvent indiquer une direction que l''usager devra suivre, une vitesse minimum à respecter, ou une voie obligatoire pour certains types d''usagers. Forme ronde, fond bleu, bordure blanche."}, {"t": "img", "src": "/cours/p16_1.jpg", "cap": "Les panneaux d''obligation"}, {"t": "h", "x": "Les panneaux de fin d''obligation"}, {"t": "img", "src": "/cours/p17_1.jpg", "cap": "Panneaux 9 à 16"}, {"t": "ul", "x": ["9. Fin de piste ou bande cyclable réservée aux cycles à 2 ou 3 roues", "10. Fin de chemin obligatoire pour les piétons", "11. Fin de chemin obligatoire pour les cavaliers", "12. Fin de vitesse minimale obligatoire", "13. Les chaînes à neige ne sont plus obligatoires", "14. Fin de voie réservée aux véhicules des services réguliers de transport en commun", "15. Fin de voie réservée aux trams", "16. Fin d''obligation selon inscription"]}, {"t": "quiz", "q": "Quelle est la forme et la couleur d''un panneau d''obligation ?", "o": ["Triangle rouge", "Rond bleu à bordure blanche", "Carré blanc", "Rond blanc à bordure rouge"], "a": 1, "e": "Rond, fond bleu, bordure blanche."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('a9004a2c-6499-5056-8cbf-e65fc203d8bc','58f24442-ddd4-543d-8cd0-c709f95375c1',3,'Les panneaux d''interdiction',7,'[{"t": "p", "x": "Les panneaux d''interdiction sont de forme ronde, à fond blanc et bordure rouge."}, {"t": "img", "src": "/cours/p18_1.jpg", "cap": "Les panneaux d''interdiction (1/2)"}, {"t": "img", "src": "/cours/p19_1.jpg", "cap": "Les panneaux d''interdiction (2/2)"}, {"t": "h", "x": "Les panneaux de fin d''interdiction"}, {"t": "img", "src": "/cours/p19_2.jpg", "cap": "Panneaux 36 à 42"}, {"t": "ul", "x": ["36. Fin de toutes les interdictions précédemment signalées et imposées aux véhicules", "37. Fin de limitation de vitesse à 70 km/h", "38. Fin d''interdiction de dépasser", "39. Fin d''interdiction de dépasser pour les véhicules de transport de marchandises dont le PTAC est supérieur à 3,5 t", "40. Fin d''interdiction de l''emploi des avertisseurs sonores", "41. Fin d''interdiction aux skieurs", "42. Accès interdit aux troupeaux"]}, {"t": "h", "x": "Les panneaux de sortie de zone"}, {"t": "img", "src": "/cours/p20_1.jpg", "cap": "Panneaux 9 à 16"}, {"t": "ul", "x": ["9. Sortie de zone", "10. Sortie de zone à stationnement unilatéral à alternance semi-mensuelle", "11 et 12. Sortie de zone à stationnement de durée limitée avec contrôle par un disque de stationnement", "13. Sortie de zone à stationnement payant", "14 et 15. Sortie de zone à stationnement unilatéral à alternance semi-mensuelle et à durée limitée contrôlée par disque", "16. Sortie de zone à 30 km/h s''appliquant sur les rues adjacentes"]}, {"t": "quiz", "q": "Quelle est la forme d''un panneau d''interdiction ?", "o": ["Triangulaire", "Ronde, fond blanc, bordure rouge", "Carrée bleue", "Rectangulaire verte"], "a": 1, "e": "Rond, fond blanc, bordure rouge."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('280cce43-dc56-5842-8eed-ff4380979e1d','58f24442-ddd4-543d-8cd0-c709f95375c1',4,'Les panneaux d''indication',6,'[{"t": "p", "x": "Les panneaux d''indication portent à la connaissance de tous les usagers des informations utiles pour leur trajet, notamment en termes de sécurité et de confort. Forme carrée ou rectangulaire, fond bleu ou blanc."}, {"t": "def", "x": [["Indications utiles", "Forme carrée ou rectangulaire, fond bleu ou blanc."], ["Indications diverses (services)", "Installations ou aménagements : restaurant, aires de jeux, station de carburant…"]]}, {"t": "img", "src": "/cours/p21_1.jpg", "cap": "Panneaux d''indications utiles"}, {"t": "img", "src": "/cours/p22_1.jpg", "cap": "Indications diverses"}, {"t": "img", "src": "/cours/p23_1.jpg", "cap": "Les panneaux d''indications"}, {"t": "img", "src": "/cours/p24_1.jpg", "cap": "Les panneaux de services"}, {"t": "quiz", "q": "Quelle est la forme d''un panneau d''indication ?", "o": ["Triangulaire", "Ronde", "Carrée ou rectangulaire", "Octogonale"], "a": 2, "e": "Carrée ou rectangulaire, fond bleu ou blanc."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('b763ab09-2692-5a2b-825c-a17b22535f5b','58f24442-ddd4-543d-8cd0-c709f95375c1',5,'Les balises',3,'[{"t": "p", "x": "Des balises de signalisation sont mises en place le long des voies du réseau routier pour guider les usagers ou leur faire part d''un risque clairement défini. Cet aménagement permet que la signalisation d''un itinéraire soit communiquée de façon homogène."}, {"t": "p", "x": "Les agents de la circulation routière permettent la bonne marche des balises : feux et panneaux. Ils se regroupent dans un ensemble appelé réseau routier et sont en rapport direct avec la police et les sapeurs-pompiers."}, {"t": "img", "src": "/cours/p26_1.jpg", "cap": "Les balises"}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('62ac50b7-a1f4-5afb-8ca8-1d80320e36fa',2,'Signalisation horizontale','Le marquage au sol : lignes, flèches, passages piétons.','🛣️','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('c871db84-5948-5b91-8e05-735ddafe36a0','62ac50b7-a1f4-5afb-8ca8-1d80320e36fa',0,'Définition et principes',4,'[{"t": "p", "x": "La signalisation horizontale, ou marquage au sol, est l''ensemble des indications peintes et dessinées au sol : lignes, flèches, indications de voies spécialisées et quelques marquages spécifiques. Elle permet d''identifier les différentes parties de la route et de savoir où l''on doit, ou ne doit pas, rouler."}, {"t": "p", "x": "Le marquage peut être présent en agglomération ou sur les routes, permanent ou temporaire."}, {"t": "key", "x": "Le marquage est de couleur blanche, ou jaune s''il est temporaire."}, {"t": "cmp", "l": ["Ligne continue", "Franchissement absolument interdit."], "r": ["Ligne discontinue", "Franchissement possible pour doubler ou traverser la chaussée."]}, {"t": "p", "x": "Lignes mixtes : franchissement possible si l''on se trouve du côté de la ligne discontinue."}, {"t": "h", "x": "Passages pour piétons et cas particulier"}, {"t": "ul", "x": ["Les piétons sont tenus d''utiliser les passages pour piétons lorsqu''il en existe à moins de 50 mètres.", "Une ligne continue large au STOP matérialise l''endroit où l''arrêt est obligatoire (pied à terre si l''on est en deux-roues)."]}, {"t": "img", "src": "/cours/p30_1.jpg", "cap": "Les principes généraux"}, {"t": "quiz", "q": "De quelle couleur est un marquage temporaire ?", "o": ["Blanc", "Jaune", "Rouge", "Bleu"], "a": 1, "e": "Blanc pour le permanent, jaune s''il est temporaire."}, {"t": "quiz", "q": "À partir de quelle distance les piétons doivent-ils utiliser un passage piéton ?", "o": ["S''il y en a un à moins de 50 m", "À moins de 200 m", "Jamais", "À moins de 5 m"], "a": 0, "e": "Lorsqu''il en existe à moins de 50 mètres."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('10532958-903a-5701-bf51-5bdee03b526a','62ac50b7-a1f4-5afb-8ca8-1d80320e36fa',1,'Les lignes et marquages',8,'[{"t": "flip", "x": [["Ligne continue", "Infranchissable ; dépassement et changement de voie interdits"], ["Ligne discontinue (trait 3 m, intervalle 10 m)", "Dépassement et changement de voie autorisés"], ["Ligne de dissuasion (3 m / 1,33 m)", "Remplace une ligne continue sur route étroite ou sinueuse : seul le dépassement de véhicules très lents est autorisé"], ["Ligne d''avertissement (3 m / 1,33 m)", "Annonce une ligne continue : on peut terminer un dépassement, pas l''entreprendre"], ["Ligne mixte", "Franchissable par le conducteur situé du côté de la ligne discontinue"], ["Ligne de rive (3 m / 3,50 m)", "Sépare la chaussée de l''accotement ; franchissable pour s''arrêter ou stationner"]]}, {"t": "tbl", "h": ["Marquage", "Signification"], "r": [["Ligne continue", "Infranchissable, dépassement et changement de voie interdits. Interdit aussi de la traverser perpendiculairement (pour sortir ou rentrer dans une rue, une cour, un garage)."], ["Ligne discontinue (trait 3 m, intervalle 10 m)", "Dépassement et changement de voie autorisés."], ["Ligne de dissuasion (trait 3 m, intervalle 1,33 m)", "Sur routes étroites ou sinueuses, remplace une ligne continue ; seul le dépassement de véhicules roulant très lentement est autorisé (tracteur agricole, voiturette, cycle…)."], ["Ligne d''avertissement (trait 3 m, intervalle 1,33 m)", "Annonce une ligne continue. Trois flèches de rabattement avertissent le conducteur. Il est possible de terminer un dépassement, mais pas de l''entreprendre."], ["Flèches de rabattement", "Indiquent la voie dans laquelle il faut se rabattre."], ["Ligne mixte", "Peut être franchie par le conducteur situé du côté de la ligne discontinue."], ["Ligne de rive (trait 3 m, intervalle 3,50 m)", "Sépare la chaussée de l''accotement, peut être franchie pour s''arrêter ou stationner. Dans les sens uniques, la ligne de rive à gauche est continue."], ["Ligne de rive (trait 20 m, intervalle 6 m)", "Annonce l''approche d''une intersection."], ["Ligne de rive (trait 38 m, intervalle 14 m)", "Sur autoroute, délimite la bande d''arrêt d''urgence (BAU) : circulation, arrêt et stationnement interdits sauf panne ou incident."], ["Ligne discontinue à traits larges", "Voies réservées à certains usagers (cycles, bus, véhicules lents) ou voies d''insertion (accélération), de décélération, de stockage."], ["Flèches directionnelles", "Imposent de suivre la ou l''une des directions indiquées."]]}, {"t": "img", "src": "/cours/p28_1.jpg", "cap": "La signalisation routière horizontale"}, {"t": "img", "src": "/cours/p29_1.jpg", "cap": "Les lignes (1)"}, {"t": "img", "src": "/cours/p31_1.jpg", "cap": "Les lignes (2)"}, {"t": "h", "x": "Lignes jaunes et bleues"}, {"t": "def", "x": [["Arrêt de bus", "Arrêt et stationnement interdits."], ["Ligne jaune continue le long du trottoir", "Arrêt et stationnement interdits."], ["Ligne jaune discontinue le long du trottoir", "Arrêt autorisé, stationnement interdit."], ["Ligne jaune continue devant une agence bancaire", "Emplacement réservé au transport de fonds : arrêt et stationnement interdits à toute heure, tous les jours."], ["Ligne continue coupée à hauteur de certaines rues ou entrées de garage", "Il est possible de la traverser perpendiculairement, mais le franchissement ou le chevauchement reste interdit (interdiction de doubler)."], ["Lignes bleues", "Délimitent les zones de stationnement à durée limitée avec contrôle par disque (stationnement gratuit)."]]}, {"t": "quiz", "q": "Que permet la ligne d''avertissement ?", "o": ["De commencer un dépassement", "De terminer un dépassement, pas de l''entreprendre", "D''accélérer", "De stationner"], "a": 1, "e": "Elle annonce une ligne continue : on peut terminer un dépassement mais pas l''entreprendre."}, {"t": "quiz", "q": "Une ligne jaune discontinue le long du trottoir signifie…", "o": ["Arrêt et stationnement interdits", "Arrêt autorisé, stationnement interdit", "Stationnement autorisé", "Zone bleue"], "a": 1, "e": "Arrêt autorisé, stationnement interdit."}, {"t": "quiz", "q": "Quelle ligne délimite la bande d''arrêt d''urgence sur autoroute ?", "o": ["Ligne de rive 38 m / 14 m", "Ligne continue", "Ligne mixte", "Ligne de dissuasion"], "a": 0, "e": "La ligne de rive à trait de 38 m et intervalle de 14 m."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('ebf257f3-ae5f-5b88-85c1-daab4c644176',3,'Les feux du véhicule','Position, croisement, route, brouillard, clignotants et autres feux.','💡','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('e9590fad-e565-5b3d-95e3-13a21f9bde90','ebf257f3-ae5f-5b88-85c1-daab4c644176',0,'Position, croisement et route',6,'[{"t": "p", "x": "Les feux de voiture permettent à la fois de mieux voir et d''être vu. Ils sont à l''avant et à l''arrière du véhicule. Une mauvaise utilisation peut être dangereuse : il existe des infractions sanctionnant l''utilisation abusive des feux et le manque d''éclairage."}, {"t": "flip", "x": [["Feux de position (veilleuses)", "Être vu à 150 m, mais pas mieux voir. Symbole : ampoule verte."], ["Feux de croisement (codes)", "Être vu et voir à 30 m. Blanc ou jaune. Symbole : phare vert, rayons vers le bas."], ["Feux de route (pleins phares)", "Voir à au moins 100 m. Très éblouissants. Symbole : phare bleu."]]}, {"t": "h", "x": "1. Feux de position (« veilleuses »)"}, {"t": "p", "x": "Les plus faibles : ils permettent d''être vu à 150 mètres, pas de mieux voir. Au nombre de 4 : deux feux blancs à l''avant, deux feux rouges à l''arrière. On les allume dès que la luminosité décline légèrement, ou à la tombée de la nuit même sur chaussée éclairée. Sur le tableau de bord : symbole d''une ampoule verte."}, {"t": "p", "x": "Seuls, ils peuvent être insuffisants quand la visibilité est compromise. Ils peuvent servir de feux de stationnement hors agglomération, la nuit, au lever du jour ou quand la visibilité est insuffisante."}, {"t": "key", "x": "Il est interdit de circuler sans feux la nuit, même en ville."}, {"t": "h", "x": "2. Feux de croisement (« codes »)"}, {"t": "p", "x": "Les plus utilisés : ils permettent d''être vu et de mieux voir la route sur 30 mètres. De couleur blanche ou jaune. On les utilise en agglomération, sur route ou autoroute, de nuit, et de jour si la pluie, la neige ou le brouillard réduisent fortement la visibilité. Ce sont les feux les plus adaptés par temps de pluie."}, {"t": "p", "x": "Leur éclairage est orienté vers le sol et éclaire plus loin du côté droit, pour croiser sans éblouir. Leur angle est réglable (selon le chargement). Tableau de bord : phare vert avec rayons vers le bas."}, {"t": "h", "x": "3. Feux de route (« pleins phares »)"}, {"t": "p", "x": "Ils permettent de voir jusqu''à au moins 100 mètres. À utiliser de nuit uniquement lorsque la chaussée n''est pas éclairée et qu''aucune voiture n''arrive en sens inverse (ils sont très éblouissants). Si un usager arrive en sens inverse, repasser obligatoirement en feux de croisement. Les « appels de phare » servent à communiquer quand le klaxon n''est pas recommandé. Tableau de bord : phare bleu aux rayons perpendiculaires."}, {"t": "quiz", "q": "À quelle distance les feux de position permettent-ils d''être vu ?", "o": ["30 m", "100 m", "150 m", "300 m"], "a": 2, "e": "Les feux de position permettent d''être vu à 150 m."}, {"t": "quiz", "q": "Quelle est la portée d''éclairage des feux de croisement ?", "o": ["30 m", "100 m", "150 m", "500 m"], "a": 0, "e": "Les feux de croisement éclairent la route sur 30 m."}, {"t": "quiz", "q": "Un véhicule arrive en sens inverse. Que faites-vous ?", "o": ["Je garde les feux de route", "Je repasse en feux de croisement", "J''éteins les feux", "J''allume les feux de brouillard"], "a": 1, "e": "Il est obligatoire de repasser en feux de croisement pour ne pas éblouir."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('4d4fea4e-e59f-51ea-b5fa-80fbf83b02b6','ebf257f3-ae5f-5b88-85c1-daab4c644176',1,'Brouillard, stop et recul',5,'[{"t": "flip", "x": [["Brouillard avant", "En complément des feux de croisement : forte pluie, brouillard, neige. Symbole vert avec vague verticale."], ["Brouillard arrière", "Brouillard ou neige UNIQUEMENT, jamais sous la pluie. Symbole orange."], ["Feux de stop", "Rouges, à l''arrière : s''allument au freinage"], ["Feux de recul", "Indiquent la marche arrière et éclairent la zone"]]}, {"t": "h", "x": "4. Feux de brouillard avant"}, {"t": "p", "x": "Utilisés en complément des feux de croisement en cas de forte pluie, de brouillard ou de chute de neige, et pour éclairer une route étroite et sinueuse non éclairée. Leur faisceau est large. Tableau de bord : symbole vert proche de celui des feux de croisement, rayons traversés par une vague verticale."}, {"t": "h", "x": "5. Feux de brouillard arrière"}, {"t": "p", "x": "Très lumineux : en cas de brouillard ou de chute de neige. Strictement interdits sous la pluie (ils éblouiraient les conducteurs derrière). Tableau de bord : symbole orange, faisceau dirigé vers la droite coupé par une vague verticale."}, {"t": "h", "x": "6. Feux de stop"}, {"t": "p", "x": "À l''arrière du véhicule, ils préviennent les usagers suivants d''un ralentissement. Ils s''allument automatiquement quand on appuie sur la pédale de frein et émettent une lumière rouge."}, {"t": "h", "x": "7. Feux de recul"}, {"t": "p", "x": "Ils indiquent que le véhicule recule et éclairent la zone de recul. Ils s''activent automatiquement en marche arrière ; un ou deux selon les modèles."}, {"t": "key", "x": "Brouillard arrière : brouillard ou neige, JAMAIS sous la pluie."}, {"t": "quiz", "q": "Peut-on utiliser le feu de brouillard arrière sous la pluie ?", "o": ["Oui", "Non, c''est strictement interdit"], "a": 1, "e": "Il est strictement interdit sous de fortes pluies : il éblouirait les conducteurs derrière vous."}, {"t": "quiz", "q": "Quelle est la couleur du symbole des feux de brouillard arrière au tableau de bord ?", "o": ["Vert", "Bleu", "Orange", "Rouge"], "a": 2, "e": "Symbole orange."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('281715b5-e1b8-56c4-a488-f95a262a02b3','ebf257f3-ae5f-5b88-85c1-daab4c644176',2,'Clignotants, détresse et autres feux',7,'[{"t": "def", "x": [["8. Feux clignotants", "Avertissent les autres usagers de l''intention de changer de direction ou de se déporter à droite ou à gauche. À utiliser à chaque changement de direction. Commande : manette à gauche du volant. Tableau de bord : flèches vers la droite et la gauche."], ["9. Feux de détresse (warning)", "Signalent une situation anormale ou dangereuse ; obligatoires en cas d''ennui mécanique ou de panne. Ils restent allumés si vous êtes arrêté sur la bande d''arrêt d''urgence ou sur la chaussée. Tableau de bord : double triangle rouge."], ["10. Feux diurnes (feux de jour)", "Utilisés la journée pour être vu, allumés en continu (anticipent tunnel, passage en forêt…), à l''avant. Utilisation facultative, mais obligatoires sur tous les véhicules neufs depuis 2012."], ["11. Feux adaptatifs et feux d''angle", "Intégrés aux projecteurs : orientent les faisceaux selon le volant et corrigent l''inclinaison (sécurité active). Les feux d''angle s''allument avec les feux de croisement ou de route si l''on roule à moins de 40 km/h clignotant activé. Facultatifs, selon les modèles."], ["12. Feux de gabarit", "Obligatoires pour les véhicules, remorques et semi-remorques de plus de 2,10 m de large. Ils font office de feux de position arrière et rendent visibles les extrémités."], ["13. Catadioptres rouges", "Dispositifs rétro-réfléchissants à l''avant, sur les côtés ou à l''arrière. Beaucoup moins visibles que les veilleuses : à garder propres."], ["14. Éclairage des vélos et motos", "Cyclomoteurs mis en circulation depuis 2004 : feux obligatoires jour et nuit. Motos de plus de 125 cm³ mises en circulation depuis le 1er janvier 1965, et toutes les autres motos mises en circulation après le 1er janvier 1988 : allumage obligatoire. Vélos : feu avant blanc, feu arrière rouge, catadioptres sur les pédales et à l''arrière ; hors agglomération la nuit, gilet rétro-réfléchissant obligatoire."]]}, {"t": "img", "src": "/cours/p37_1.jpg", "cap": "Clignotants"}, {"t": "img", "src": "/cours/p37_2.jpg", "cap": "Feux de détresse"}, {"t": "quiz", "q": "Que signale le double triangle rouge au tableau de bord ?", "o": ["Feux de route", "Feux de détresse", "Feux de brouillard", "Feux de gabarit"], "a": 1, "e": "Le double triangle rouge est le symbole des feux de détresse."}, {"t": "quiz", "q": "À partir de quelle largeur les feux de gabarit sont-ils obligatoires ?", "o": ["1,50 m", "2,10 m", "3 m", "4 m"], "a": 1, "e": "Au-delà de 2,10 m de largeur."}]'::jsonb,'Le cours mentionne une amende en euros pour l''absence de feux de jour des motos : montant non adapté au Sénégal, volontairement non repris ici. À vérifier.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('30e3e7bf-fe58-5247-ac96-8ab57aa5877e','ebf257f3-ae5f-5b88-85c1-daab4c644176',3,'Quels feux dans quelle situation ?',5,'[{"t": "img", "src": "/cours/p39_1.jpg", "cap": "Tableau récapitulatif des feux selon la situation"}, {"t": "tbl", "h": ["Situation", "Feux à utiliser"], "r": [["Ville éclairée", "Position OU croisement"], ["Ville non éclairée", "Croisement OU route"], ["Chaussée éclairée (hors agglomération)", "Croisement"], ["Chaussée non éclairée", "Croisement OU route (+ brouillard avant si route étroite et sinueuse)"], ["Pluie", "Croisement (+ brouillard avant en cas de forte pluie)"], ["Neige", "Croisement + brouillard avant + brouillard arrière"], ["Brouillard", "Croisement + brouillard avant + brouillard arrière"]]}, {"t": "img", "src": "/cours/p39_2.jpg", "cap": "Symboles et distances"}, {"t": "tbl", "h": ["Feu", "Symbole", "Distance"], "r": [["Position", "Ampoule verte", "Vu à 150 m"], ["Croisement", "Phare vert", "30 m"], ["Route", "Phare bleu", "100 m"], ["Brouillard avant", "Vert avec vague verticale", "—"], ["Brouillard arrière", "Orange", "—"]]}, {"t": "key", "x": "Position 150 m (vu) · Croisement 30 m · Route 100 m."}, {"t": "quiz", "q": "Que faut-il utiliser sous une forte pluie ?", "o": ["Feux de route", "Croisement (+ brouillard avant en cas de forte pluie)", "Brouillard arrière", "Aucun feu"], "a": 1, "e": "Croisement, et brouillard avant en cas de forte pluie. Jamais le brouillard arrière."}, {"t": "quiz", "q": "Par brouillard, quels feux utilise-t-on ?", "o": ["Croisement seul", "Croisement, brouillard avant et brouillard arrière", "Route uniquement", "Position uniquement"], "a": 1, "e": "Croisement + brouillard avant + brouillard arrière."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('06a89590-0e79-501f-b687-8eca655d0c81',4,'L''arrêt et le stationnement','Définitions, où s''arrêter, où stationner, où c''est interdit.','🅿️','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('8f8d915b-9c2b-5299-9260-f11c2334b72b','06a89590-0e79-501f-b687-8eca655d0c81',0,'Arrêt, stationnement, immobilisation',4,'[{"t": "cmp", "l": ["Arrêt", "Immobilisation momentanée d''un véhicule pendant le temps nécessaire pour embarquer ou débarquer des personnes ou des choses ; le conducteur reste aux commandes ou à proximité pour pouvoir le déplacer."], "r": ["Stationnement", "Immobilisation d''un véhicule au-delà du temps nécessaire pour embarquer ou débarquer des personnes ou des choses."]}, {"t": "key", "x": "La différence entre arrêt et stationnement ne tient pas à la durée, mais au type d''immobilisation : l''arrêt est temporaire, le stationnement est une immobilisation définitive."}, {"t": "def", "x": [["Véhicule immobilisé", "Véhicule stoppé dans son mouvement devant des feux ou dans une file, par exemple. Contrairement à l''arrêt et au stationnement, la situation n''est pas volontaire."]]}, {"t": "img", "src": "/cours/p46_1.jpg", "cap": "Arrêt et stationnement : définitions"}, {"t": "quiz", "q": "Un véhicule stoppé devant un feu rouge est…", "o": ["à l''arrêt", "en stationnement", "immobilisé", "en panne"], "a": 2, "e": "Il est immobilisé : la situation n''est pas volontaire."}, {"t": "quiz", "q": "Quelle est la différence entre arrêt et stationnement ?", "o": ["La durée uniquement", "Le type d''immobilisation", "La couleur du véhicule", "Aucune"], "a": 1, "e": "Ce n''est pas la durée mais le type d''immobilisation."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('f1f8e469-2551-5410-b890-52a35e64a211','06a89590-0e79-501f-b687-8eca655d0c81',1,'Où s''arrêter et stationner ?',5,'[{"t": "h", "x": "Les véhicules"}, {"t": "ul", "x": ["À droite par rapport au sens de la marche (sauf chaussée à sens unique ; sauf dans les zones de rencontre et résidentielles).", "Hors de la chaussée : sur l''accotement de plain-pied ; hors agglomération, sur tous les accotements. Laisser au minimum 1,5 m de largeur aux piétons du côté extérieur de la voie publique.", "S''il est impossible de faire autrement : en partie sur la chaussée et en partie sur l''accotement, ou sur la chaussée."]}, {"t": "h", "x": "Si le véhicule est totalement ou partiellement sur la chaussée"}, {"t": "ul", "x": ["Parallèlement au bord de la chaussée.", "À la plus grande distance possible de l''axe de la chaussée.", "En une seule file.", "Exception : les motocyclettes sans side-car ni remorque peuvent stationner perpendiculairement sur le côté de la chaussée sans dépasser le marquage indiqué."]}, {"t": "h", "x": "Bicyclettes et cyclomoteurs à deux roues"}, {"t": "p", "x": "En dehors de la chaussée et des zones de stationnement, sans gêner ni rendre dangereuse la circulation des autres usagers, ou aux endroits signalés par un signal P muni d''un panneau additionnel M1 ou M8."}, {"t": "h", "x": "Motocyclettes"}, {"t": "p", "x": "Hors de la chaussée et des zones de stationnement, de manière à ne pas gêner ni rendre dangereuse la circulation des autres usagers."}, {"t": "key", "x": "Règle générale : il est interdit d''arrêter ou de stationner partout où le véhicule peut constituer un danger ou gêner les autres usagers sans nécessité."}, {"t": "quiz", "q": "Combien de largeur faut-il laisser aux piétons sur l''accotement ?", "o": ["0,5 m", "1 m", "1,5 m", "3 m"], "a": 2, "e": "Au minimum 1,5 m."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('807f3b0a-9732-5148-a19a-6209ed21db72','06a89590-0e79-501f-b687-8eca655d0c81',2,'Où l''arrêt et le stationnement sont interdits',7,'[{"t": "img", "src": "/cours/p41_1.jpg", "cap": "Les panneaux d''arrêt et de stationnement"}, {"t": "h", "x": "Zones d''interdiction de l''arrêt et du stationnement"}, {"t": "ul", "x": ["Intersection", "Virage", "Sommet de côte", "Au niveau d''un passage à niveau", "Sur les trottoirs", "Sur les passages piétons", "Sur les voies réservées aux cycles, bus, taxis ou véhicules lents", "En double file (avec ligne continue)", "Sur les ponts ou dans les tunnels", "À proximité d''une ligne continue", "Sur les bandes d''arrêt d''urgence", "Si le véhicule masque la signalisation ou les feux", "À côté d''une bouche à incendie", "Sur un emplacement d''arrêt d''urgence"]}, {"t": "img", "src": "/cours/p44_1.jpg", "cap": "Piste cyclable ≠ parking"}, {"t": "img", "src": "/cours/p44_2.jpg", "cap": "Passage piétons ≠ parking"}, {"t": "h", "x": "Détail des distances"}, {"t": "ul", "x": ["Pistes cyclables : et à moins de 5 m de l''endroit où les cyclistes quittent la piste pour circuler sur la chaussée ou la rejoindre.", "Passages à niveau ; passages pour piétons et cyclistes, et sur la chaussée à moins de 5 m en deçà.", "Routes pour automobiles et autoroutes, sauf signal P.", "Dans les passages inférieurs, tunnels et sous les ponts, sauf réglementation locale.", "Quand la visibilité est insuffisante : à proximité d''une côte, dans un virage.", "Aux abords des carrefours, à moins de 5 m du prolongement du bord le plus rapproché de la chaussée transversale.", "À moins de 20 m en deçà des signaux lumineux de circulation (aux carrefours ou en dehors), sauf réglementation locale. Si le véhicule fait moins de 1,65 m de haut et que le signal est à plus de 2 m au-dessus de la chaussée, le stationnement est autorisé."]}, {"t": "img", "src": "/cours/p45_1.jpg", "cap": "Extrait des Cahiers du moniteur de la mobilité"}, {"t": "img", "src": "/cours/p46_2.jpg", "cap": "Arrêts et stationnements gênants ou dangereux"}, {"t": "quiz", "q": "À quelle distance d''un passage piéton est-il interdit de s''arrêter ?", "o": ["Sur le passage et à moins de 5 m en deçà", "Seulement sur le passage", "À moins de 50 m", "À moins de 1 m"], "a": 0, "e": "Sur les passages pour piétons et sur la chaussée à moins de 5 m en deçà."}, {"t": "quiz", "q": "Peut-on stationner sur un trottoir ?", "o": ["Oui", "Non, c''est interdit"], "a": 1, "e": "Arrêt et stationnement sont interdits sur les trottoirs."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('4e814377-0c6a-5fbf-a356-0c7ce3471ecc','06a89590-0e79-501f-b687-8eca655d0c81',3,'Où seul le stationnement est interdit',4,'[{"t": "ul", "x": ["À moins de 1 mètre devant ou derrière un autre véhicule à l''arrêt ou en stationnement, et partout où le véhicule empêcherait l''accès d''un autre véhicule ou son dégagement.", "En double file (si pas de ligne continue) : stationnement interdit mais arrêt toléré.", "Aux sorties de garages : stationnement interdit mais arrêt toléré.", "Le long d''une ligne jaune discontinue : arrêt possible, stationnement interdit."]}, {"t": "key", "x": "Trait continu : arrêt et stationnement interdits. Trait discontinu : possibilité d''arrêt, stationnement interdit."}, {"t": "img", "src": "/cours/p46_3.jpg", "cap": "Stationnement interdit mais arrêt toléré"}, {"t": "h", "x": "Les feux d''un véhicule arrêté ou stationné"}, {"t": "p", "x": "De nuit, en ou hors agglomération, les véhicules arrêtés ou stationnés sur la chaussée doivent être signalés par leurs feux de position. Sur un parking ou sur l''accotement, les véhicules gardent leurs feux éteints."}, {"t": "img", "src": "/cours/p47_1.jpg", "cap": "Les feux à l''arrêt et en stationnement"}, {"t": "quiz", "q": "Un véhicule stationné la nuit sur la chaussée doit être signalé par…", "o": ["ses feux de route", "ses feux de position", "ses feux de brouillard arrière", "aucun feu"], "a": 1, "e": "Par ses feux de position. Sur un parking ou l''accotement, les feux restent éteints."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('9a43dd60-6a91-53aa-a5c7-40d094082224',5,'Le dépassement','Conditions, interdictions, distances et rabattement.','🚙','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('7392241b-96ab-51fc-852b-bb668e9e4d4d','9a43dd60-6a91-53aa-a5c7-40d094082224',0,'Définition et généralités',3,'[{"t": "p", "x": "Un dépassement est le fait de rouler pendant un instant, en général relativement court, à côté d''un autre usager de la chaussée (véhicule ou non : animal, piéton, engin à roues ; ou groupe de plusieurs usagers) à une vitesse supérieure à la sienne, dans le but de le précéder."}, {"t": "key", "x": "Les dépassements s''effectuent généralement par la gauche."}, {"t": "h", "x": "On peut dépasser par la droite"}, {"t": "ul", "x": ["Un usager (véhicule, moto, vélo) qui veut tourner à gauche avec signalement (clignotant).", "Lorsque la circulation est en file ininterrompue, comme dans les bouchons.", "Lorsqu''on est dans une voie à 2 ou plusieurs files, comme la VDN ou l''autoroute."]}, {"t": "img", "src": "/cours/p50_1.jpg", "cap": "Rabattement sur une voie à plusieurs files"}, {"t": "quiz", "q": "Par quel côté dépasse-t-on en général ?", "o": ["Par la droite", "Par la gauche", "Indifféremment"], "a": 1, "e": "Les dépassements s''effectuent généralement par la gauche."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('cca74318-cec2-5be6-9070-8a5de9701395','9a43dd60-6a91-53aa-a5c7-40d094082224',1,'Les conditions pour dépasser',6,'[{"t": "h", "x": "1. Bonne visibilité"}, {"t": "p", "x": "La visibilité doit être suffisante. Sur une route à double sens à deux voies, il faut au minimum 500 m de visibilité quand on roule à 90 km/h. Il faut voir en face (donc ne pas trop coller le véhicule de devant) et savoir s''il sera possible de se rabattre. Effectuez les vérifications visuelles nécessaires avant de dépasser."}, {"t": "h", "x": "2. Absence d''interdiction"}, {"t": "p", "x": "Voir la leçon « Les interdictions de dépasser »."}, {"t": "h", "x": "3. Absence d''obstacles"}, {"t": "ul", "x": ["Obstacle devant : un usager en face.", "Obstacle derrière (regardez bien les rétroviseurs) : un usager derrière qui est en train de dépasser ou a l''intention de le faire."]}, {"t": "h", "x": "4. Marquer votre intention : signaler"}, {"t": "p", "x": "Toujours avant un changement de voie, signalez votre direction : c''est une obligation."}, {"t": "h", "x": "5. Accélération : + 20 km/h minimum"}, {"t": "p", "x": "Il faut une réserve de vitesse suffisante, sans dépasser les limitations de vitesse. L''écart de vitesse entre votre voiture et celle à dépasser est de + 20 km/h minimum."}, {"t": "h", "x": "Distance latérale de sécurité"}, {"t": "ul", "x": ["1 m en agglomération (en ville)", "1,5 m hors agglomération"]}, {"t": "h", "x": "Rabattement"}, {"t": "p", "x": "Un dépassement se termine toujours par un rabattement : retour sur la voie la plus à droite. Pour se rabattre, il faut signaler et vérifier dans les rétroviseurs que l''on a bien dépassé le véhicule."}, {"t": "key", "x": "Dépasser : visibilité · aucune interdiction · aucun obstacle · signaler · +20 km/h · 1 m (ville) / 1,5 m (hors agglomération) · se rabattre en signalant."}, {"t": "img", "src": "/cours/p51_1.jpg", "cap": "Hors agglomération avec des obstacles permanents"}, {"t": "img", "src": "/cours/p51_2.jpg", "cap": "Indiscipline routière"}, {"t": "quiz", "q": "Quelle distance latérale respecter hors agglomération ?", "o": ["0,5 m", "1 m", "1,5 m", "3 m"], "a": 2, "e": "1,5 m hors agglomération, 1 m en agglomération."}, {"t": "quiz", "q": "Quel écart de vitesse minimum faut-il pour dépasser ?", "o": ["+ 5 km/h", "+ 10 km/h", "+ 20 km/h", "+ 50 km/h"], "a": 2, "e": "Un écart de + 20 km/h minimum."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('26241d6a-a702-5d6f-9fe7-8a19e61b2b04','9a43dd60-6a91-53aa-a5c7-40d094082224',2,'Les interdictions de dépasser',4,'[{"t": "p", "x": "Le dépassement peut être interdit dans des situations clairement énoncées par le code, qui pourraient représenter un risque pour le conducteur ou les autres usagers."}, {"t": "h", "x": "Le dépassement est interdit"}, {"t": "ul", "x": ["Par la droite", "Sur ligne continue, ligne de dissuasion, ligne d''avertissement et ligne mixte (si l''on est du côté de la ligne continue)", "Au niveau des panneaux d''interdiction de dépasser", "Dans une intersection", "Dans un virage", "Au sommet de côte", "Dans une montagne", "Au niveau d''un passage à niveau (si la barrière n''est pas levée)", "Sur les passages piétons", "Sur les ponts ou dans les tunnels (en cas d''une seule file de circulation)", "À proximité d''une ligne continue", "Sur les bandes d''arrêt d''urgence"]}, {"t": "quiz", "q": "Peut-on dépasser dans un virage ?", "o": ["Oui", "Non"], "a": 1, "e": "Le dépassement est interdit dans un virage."}, {"t": "quiz", "q": "Peut-on dépasser sur un passage piétons ?", "o": ["Oui", "Non"], "a": 1, "e": "Le dépassement est interdit sur les passages piétons."}]'::jsonb,'') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('d7df0ad5-5063-5773-95f8-9f4f45d9c007',6,'Les règles de priorité','Priorité à droite, rond-point, agents, feux et panneaux.','🚦','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('8aea0c59-336c-5ce3-908d-fbcb95e7ecb1','d7df0ad5-5063-5773-95f8-9f4f45d9c007',0,'Règles générales',4,'[{"t": "key", "x": "La priorité n''est pas un droit absolu."}, {"t": "p", "x": "Lors du franchissement d''une intersection ou d''un rond-point, l''usager doit ralentir en contrôlant son rétroviseur intérieur et observer les autres usagers pour déterminer leurs intentions. On respecte toujours les règles de priorité en fonction des panneaux, des feux ou des agents."}, {"t": "cmp", "l": ["Dans une intersection", "La priorité appartient aux véhicules venant de droite : priorité à droite."], "r": ["Dans un rond-point", "La priorité appartient aux véhicules venant de gauche : priorité à gauche."]}, {"t": "p", "x": "Cette règle n''est valable qu''en l''absence d''agents de sécurité, de feux et de panneaux."}, {"t": "img", "src": "/cours/p54_1.jpg", "cap": "Rond-point en forme de T : priorité aux véhicules venant de gauche"}, {"t": "ul", "x": ["Intersections en forme de K, T ou Y : la priorité appartient aux véhicules venant de droite.", "Un piéton présent sur la chaussée est prioritaire : il est vulnérable sur une bande circulable."]}, {"t": "quiz", "q": "Dans une intersection sans signalisation, qui a la priorité ?", "o": ["Le véhicule venant de gauche", "Le véhicule venant de droite", "Le plus rapide", "Le plus gros"], "a": 1, "e": "Priorité à droite dans une intersection."}, {"t": "quiz", "q": "Dans un rond-point (règle générale du cours), la priorité est…", "o": ["à droite", "à gauche", "aux piétons uniquement", "au plus rapide"], "a": 1, "e": "Priorité aux véhicules venant de gauche dans un rond-point."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('2214ff88-2a36-527c-8d88-a70f19553c6c','d7df0ad5-5063-5773-95f8-9f4f45d9c007',1,'Agents, feux et panneaux',6,'[{"t": "key", "x": "Les agents priment sur les feux et les panneaux. Les feux priment sur les panneaux."}, {"t": "img", "src": "/cours/p53_1.jpg", "cap": "Agent de la circulation"}, {"t": "def", "x": [["Agent de sécurité", "Je passe si l''agent est de profil. Je m''arrête si l''agent est en face ou de dos."], ["Feux tricolores", "Je passe au vert et je m''arrête au jaune et au rouge. Je ralentis devant un feu jaune clignotant."], ["Panneaux de priorité", "Dans un rond-point ou une intersection sans agent ni feux, on suit les indications des panneaux."]]}, {"t": "img", "src": "/cours/p56_1.jpg", "cap": "Panneaux d''intersections et de priorités"}, {"t": "img", "src": "/cours/p57_1.jpg", "cap": "Particularité : panneaux accompagnant certains panneaux d''intersection"}, {"t": "img", "src": "/cours/p57_2.jpg", "cap": "Les panneaux de priorité (1) et de non-priorité (2)"}, {"t": "quiz", "q": "Un agent de circulation est en face de vous, bras tendus. Vous…", "o": ["passez", "vous arrêtez", "ralentissez seulement"], "a": 1, "e": "Je m''arrête si l''agent est en face ou de dos ; je passe s''il est de profil."}, {"t": "quiz", "q": "Qui prime en cas de conflit ?", "o": ["Les panneaux sur les feux", "Les feux sur les agents", "Les agents sur les feux et les panneaux", "Aucun ordre"], "a": 2, "e": "Les agents priment sur les feux et les panneaux ; les feux priment sur les panneaux."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('8c4063fa-a0d0-56dd-8407-a639ec20cf67','d7df0ad5-5063-5773-95f8-9f4f45d9c007',2,'Sujet de test : priorités',5,'[{"t": "p", "x": "Voici un exemple de sujet de test (Test n°2) : 8 situations de priorité, avec un ordre de passage à déterminer. Observe chaque situation, applique les règles vues dans les leçons précédentes, puis vérifie avec ton moniteur."}, {"t": "img", "src": "/cours/p55_1.jpg", "cap": "Test n°2 – Ordre de passage"}, {"t": "key", "x": "L''image n°8 est un cas particulier : interdiction de dépasser dans un virage, mais aussi lorsque le véhicule est à proximité d''une ligne continue."}]'::jsonb,'Contenu repris du cours d''origine. Certaines images, codes de signaux (ex. A13a, F4a) et références semblent issus d''un code étranger : à vérifier avec la réglementation sénégalaise avant publication.') on conflict (id) do nothing;
insert into public.course_chapters(id,position,title,summary,icon,status) values ('5029f176-bec4-5fae-99fc-42b4872f91d8',7,'Entraînement et examens blancs','Teste-toi avec les mini-jeux et les examens blancs de l''application.','📝','draft') on conflict (id) do nothing;
insert into public.course_sections(id,chapter_id,position,title,est_minutes,blocks,admin_note) values ('c2cb1118-c5aa-5794-9587-09b17667d58a','5029f176-bec4-5fae-99fc-42b4872f91d8',0,'Passer à la pratique',2,'[{"t": "p", "x": "Tu as parcouru tout le programme : signalisation verticale et horizontale, feux, arrêt et stationnement, dépassement et priorités. Il est temps de t''entraîner."}, {"t": "key", "x": "Conseil : refais les leçons où tu as hésité, puis passe un mini-jeu. Les questions ratées sont gardées dans « Mes erreurs »."}, {"t": "go", "l": "🎮 Mini-jeux, quiz et examens blancs", "h": "/eleve/quiz"}, {"t": "go", "l": "🎯 M''entraîner sur mes erreurs", "h": "/eleve/erreurs"}]'::jsonb,'') on conflict (id) do nothing;
