-- ADAPT'AUTO LAB - Cours (Apprentissage) : tables + import du PDF (brouillon : visible par l'admin seulement)
create table if not exists public.course_chapters (id uuid primary key, position int not null default 0, title text not null, summary text not null default '', icon text not null default '📘', status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now());
create table if not exists public.course_sections (id uuid primary key, chapter_id uuid not null references public.course_chapters(id) on delete cascade, position int not null default 0, title text not null, est_minutes int not null default 3, blocks jsonb not null default '[]'::jsonb, admin_note text not null default '');
create table if not exists public.course_progress (user_id uuid not null references auth.users(id) on delete cascade, section_id uuid not null references public.course_sections(id) on delete cascade, completed_at timestamptz not null default now(), primary key (user_id, section_id));
alter table public.course_chapters enable row level security; alter table public.course_sections enable row level security; alter table public.course_progress enable row level security;
drop policy if exists "cc: admin" on public.course_chapters; drop policy if exists "cc: élèves" on public.course_chapters; drop policy if exists "cs: admin" on public.course_sections; drop policy if exists "cs: élèves" on public.course_sections;
drop policy if exists "cp: lecture" on public.course_progress; drop policy if exists "cp: ajout" on public.course_progress; drop policy if exists "cp: suppression" on public.course_progress;
create policy "cc: admin" on public.course_chapters for all using (public.is_admin()) with check (public.is_admin());
create policy "cc: élèves" on public.course_chapters for select using (status = 'published');
create policy "cs: admin" on public.course_sections for all using (public.is_admin()) with check (public.is_admin());
create policy "cs: élèves" on public.course_sections for select using (exists (select 1 from public.course_chapters c where c.id = chapter_id and c.status = 'published'));
create policy "cp: lecture" on public.course_progress for select using (user_id = auth.uid() or public.is_admin());
create policy "cp: ajout" on public.course_progress for insert with check (user_id = auth.uid() and exists (select 1 from public.course_sections s where s.id = section_id));
create policy "cp: suppression" on public.course_progress for delete using (user_id = auth.uid());
